import { describe, expect, it } from "vitest";
import { exec, ExecError } from "../src/util/exec.js";

// The children are node itself (`process.execPath -e …`), so these run on every OS.
const node = process.execPath;

describe("exec", () => {
  it("drains both pipes and passes stdin", async () => {
    // The 200 KB of stderr is generated by the child: passing it through argv/env would exceed Linux's
    // per-string limit (MAX_ARG_STRLEN, 128 KB) and fail the spawn with E2BIG.
    const script =
      "const d = []; process.stdin.on('data', (c) => d.push(c)); process.stdin.on('end', () => {" +
      " process.stdout.write(Buffer.concat(d)); process.stderr.write('x'.repeat(200000), () => { process.exitCode = 3; }); });";
    const out = await exec(node, ["-e", script], { stdin: Buffer.from("input") });
    expect(out.stdout.toString("utf8")).toBe("input");
    expect(out.stderr).toHaveLength(200_000);
    expect(out.status).toBe(3);
    expect(out.signal).toBeNull();
    expect(out.timedOut).toBe(false);
  });

  it("closes stdin when none is given", async () => {
    const out = await exec(node, ["-e", "process.stdin.on('data', (c) => process.stdout.write(c))"]);
    expect(out.stdout.length).toBe(0);
    expect(out.status).toBe(0);
  });

  it("kills on timeout", async () => {
    const started = Date.now();
    const out = await exec(node, ["-e", "setTimeout(() => {}, 60000)"], { timeoutMs: 200 });
    // the child outlives the bound, so only the kill can end it in time; the bound is generous (CI runners stall)
    expect(Date.now() - started).toBeLessThan(30_000);
    expect(out.timedOut).toBe(true);
    expect(out.status).toBeNull();
    expect(out.signal).toBe("SIGTERM");
  });

  // Windows has no catchable SIGTERM: `kill("SIGTERM")` already terminates the process, so there is
  // nothing to escalate (genuinely unavailable there, not a product difference).
  it.skipIf(process.platform === "win32")("escalates to SIGKILL when SIGTERM is ignored", async () => {
    // A child of its own (e.g. `sh -c 'trap ...; sleep 30'`) would keep the stdio pipes open after the
    // SIGKILL, so the ignoring process must be leaf-less: node itself.
    const out = await exec(node, ["-e", "process.on('SIGTERM', () => {}); setInterval(() => {}, 1000)"], {
      timeoutMs: 200,
    });
    expect(out.timedOut).toBe(true);
    expect(out.signal).toBe("SIGKILL");
  });

  it("rejects on spawn failure", async () => {
    await expect(exec("/nonexistent/binary", [])).rejects.toBeInstanceOf(ExecError);
  });

  it("rejects when maxBuffer overflows", async () => {
    await expect(exec(node, ["-e", "process.stdout.write('x'.repeat(1000))"], { maxBuffer: 10 })).rejects.toBeInstanceOf(ExecError);
  });

  it("merges env and removes undefined keys", async () => {
    process.env.RG_B = "inherited"; // removed although the parent has it
    try {
      const out = await exec(node, ["-e", "process.stdout.write((process.env.RG_A ?? '') + '|' + (process.env.RG_B ?? 'unset'))"], {
        env: { RG_A: "1", RG_B: undefined },
      });
      expect(out.stdout.toString("utf8")).toBe("1|unset");
    } finally {
      delete process.env.RG_B;
    }
  });
});
